from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parents[3];data=json.loads((ROOT/'experiments/pudding-samples/evidence/promotion.json').read_text())['samples'];cards=[]
entries={r['id']:f'{p.parent.parent.name}/{r["mini"]["root"]}/index.html'
         for p in (ROOT/'workflows').glob('build-*/samples/catalog.json')
         for r in json.loads(p.read_text())['samples'] if 'mini' in r}
for category,label in [('page/general','内容页 · 图像与叙事'),('page/chart','内容页 · 图表与数据'),('interaction/general','交互页 · 模型与规则')]:
 rows=[r for r in data if r['category']==category];cards.append(f'<section><h2>{label} <small>{len(rows)}</small></h2><div class="grid">')
 for r in rows:
  href=entries[r['id']];shot=r['sample_dir'].removeprefix('workflows/')+'/shots/00.png';title=html.escape(r['title']);cards.append(f'<article><a href="{href}"><img loading="lazy" src="{shot}" alt="{title}的实际运行画面"></a><h3>{title}</h3><p>{r["id"]}</p><div class="actions"><button data-entry="{href}" data-title="{title}">嵌入预览</button><a href="{href}">独立打开 ↗</a><a href="{href.replace("index.html","SAMPLE.md")}">来源</a></div></article>')
 cards.append('</div></section>')
css='''*{box-sizing:border-box}body{margin:0;background:#faf9f6;color:#242523;font-family:Arial,"Noto Sans SC",sans-serif}main{max-width:1440px;margin:auto;padding:36px 28px}header{border-bottom:2px solid;padding:0 0 26px}h1{font-size:42px;letter-spacing:-1px;margin:12px 0}header p{color:#555;line-height:1.7}h2{font-size:24px;margin:40px 0 20px}small{font-size:14px;color:#666;margin-left:10px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:30px 22px}article{min-width:0;border-bottom:1px solid #ccc;padding-bottom:24px}article img{width:100%;aspect-ratio:16/9;object-fit:cover;object-position:top;border:1px solid #ddd}h3{margin:16px 0 8px;font-size:21px}article p{color:#666;font:13px monospace;overflow-wrap:anywhere}.actions{display:flex;align-items:center;gap:14px;flex-wrap:wrap;font-size:14px}a{color:inherit}button{font:inherit;padding:8px 12px;border:1px solid #aaa;background:white;cursor:pointer}button:focus-visible,a:focus-visible{outline:3px solid #277ac3;outline-offset:3px}dialog{padding:0;border:1px solid #888;width:calc(100vw - 24px);max-width:1680px;height:calc(100dvh - 24px);max-height:none;background:white}dialog::backdrop{background:#000a}.toolbar{height:52px;display:flex;align-items:center;gap:14px;padding:8px 14px;border-bottom:1px solid #ddd}.toolbar strong{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.toolbar a{font-size:14px}iframe{display:block;border:0;width:100%;height:calc(100% - 52px)}footer{margin-top:40px;padding-top:20px;border-top:1px solid #ccc;color:#555;font-size:14px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){main{padding:22px 16px}.grid{grid-template-columns:1fr}h1{font-size:32px}.toolbar{gap:8px}.toolbar strong{font-size:14px}}'''
js='''const dialog=document.querySelector('dialog'),frame=dialog.querySelector('iframe');let opener;document.querySelectorAll('[data-entry]').forEach(b=>b.addEventListener('click',()=>{opener=b;dialog.querySelector('strong').textContent=b.dataset.title;dialog.querySelector('a').href=b.dataset.entry;frame.title=b.dataset.title;frame.src=b.dataset.entry;dialog.showModal()}));dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{frame.src='about:blank';opener?.focus()});'''
(ROOT/'workflows/index.html').write_text('<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pudding · 正式 Samples</title><style>'+css+'</style><main><header><span>NOTALE / APPROVED SAMPLES</span><h1>Pudding · 29 个正式样本</h1><p>已于 2026 年 9 月 7 日统一通过审阅，按现有内容页与交互页分类入库。<br>原素材与完整交互保留，每项提供独立运行入口、可读源码包和来源记录。</p></header>'+''.join(cards)+'<footer>分类注册：build-page / build-interaction · 各样本附来源与原作复核记录</footer></main><dialog aria-label="样本预览"><div class="toolbar"><strong></strong><a target="_blank" rel="noopener">独立打开 ↗</a><button>关闭</button></div><iframe allow="autoplay; fullscreen" title="样本预览"></iframe></dialog><script>'+js+'</script></html>')
print('Wrote classified formal gallery')
